mapper.select:
	 select 
		subinfo.delaynum as delaynum,
		subinfo.delayingnum as delayingnum,
		subinfo.sendnum as sendnum,

		DATE_FORMAT(subinfo.mindate,'%Y-%m-%d') as mindate,

		DATE_FORMAT(subinfo.maxdate,'%Y-%m-%d') as maxdate,
		(subinfo.delaynum+subinfo.delayingnum+subinfo.sendnum) as totalnum,
		subinfo.reporttype as reporttype
	from 
	 (
		select
		   	delayData.delaynum as delaynum,
		    delayingData.mindate as mindate,
		    delayingData.maxdate as maxdate,
		    delayingData.delayingnum as delayingnum,
		    sendData.sendnum as sendnum,
		   	'1' as reporttype
		   	FROM
		   	(select count(ces1.SUBMIT_STATUS) as delaynum from CHB_EQU_SUB  ces1 WHERE ces1.CHB_SUBMIT_DEADLINE <= STR_TO_DATE(#{searchDateYesterday,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and  ces1.SUBMIT_STATUS=#{NO_SUBMIT}



	                	null) or ces1.CREATE_DEPT in (

	                #{item,jdbcType=VARCHAR}

            	)





	                    null) OR ces1.ORG_CODE in (

                #{item,jdbcType=VARCHAR}

               )




	                	null) or ces1.DEPT_CODE in (

	                #{item,jdbcType=VARCHAR}

            	)

		   	 ) delayData ,
			(select count(ces2.SUBMIT_STATUS) as delayingnum , min(ces2.SUBMIT_DEADLINE) as mindate, max(ces2.CHB_SUBMIT_DEADLINE) as maxdate from CHB_EQU_SUB  ces2 WHERE ces2.CHB_SUBMIT_DEADLINE > STR_TO_DATE(#{searchDateYesterday,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and ces2.SUBMIT_DEADLINE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and ces2.SUBMIT_STATUS=#{NO_SUBMIT} 


				#{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}


			) delayingData,
			(select count(ces3.SUBMIT_STATUS) as sendnum from CHB_EQU_SUB  ces3 WHERE ces3.CHB_SUBMIT_DEADLINE > STR_TO_DATE(#{searchDate,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and ces3.SUBMIT_STATUS=#{NO_SUBMIT}  


				#{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}


			) sendData
   		union all
   		select
		   	delayData.delaynum as delaynum,
		    delayingData.mindate as mindate,
		    delayingData.maxdate as maxdate,
		    delayingData.delayingnum as delayingnum,
		    sendData.sendnum as sendnum,
		   	'2' as reporttype
		   	FROM
		   	(select count(ciis1.SEND_STATUS) as delaynum from CHB_INVESTHOLD_INFO_SUB  ciis1 WHERE ciis1.CHB_SUBMIT_DEADLINE <= STR_TO_DATE(#{searchDateYesterday,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and  ciis1.SEND_STATUS=#{NO_SUBMIT} 


				#{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}


		   	) delayData ,
			(select count(ciis2.SEND_STATUS) as delayingnum , min(ciis2.SUBMIT_DEADLINE) as mindate, max(ciis2.CHB_SUBMIT_DEADLINE) as maxdate from CHB_INVESTHOLD_INFO_SUB  ciis2 WHERE ciis2.CHB_SUBMIT_DEADLINE > STR_TO_DATE(#{searchDateYesterday,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and ciis2.SUBMIT_DEADLINE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and ciis2.SEND_STATUS=#{NO_SUBMIT}


				#{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}


			 ) delayingData,
			(select count(ciis3.SEND_STATUS) as sendnum from CHB_INVESTHOLD_INFO_SUB  ciis3 WHERE ciis3.SUBMIT_DEADLINE > STR_TO_DATE(#{searchDate,jdbcType=VARCHAR}, '%Y-%m-%d HH24:mi:ss') and ciis3.SEND_STATUS=#{NO_SUBMIT} 


				#{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}


			) sendData

	)subinfo
